// Look at the polish branch's nine items at three window sizes.
//
// Run from a worktree's frontend/ directory (so playwright resolves), with both
// halves of the app already up:
//
//   APP=http://localhost:5183 OUT=/abs/dir node /abs/path/polish-look.mjs
//
// Writes PNGs and one findings.json (focus checks, overflow checks, titles).
// A picture is evidence, not an assertion: nothing here fails a build.
import { createRequire } from "node:module";
import { mkdirSync, writeFileSync } from "node:fs";

const require = createRequire(`${process.cwd()}/`);
const { chromium } = require("@playwright/test");

const APP = process.env.APP ?? "http://localhost:5183";
const OUT = process.env.OUT ?? `${process.cwd()}/polish-look`;
mkdirSync(OUT, { recursive: true });

const WINDOWS = [
  { width: 1600, height: 1000 },
  { width: 1440, height: 900 },
  { width: 1280, height: 800 },
];
const findings = {};

async function laidOut(page, tiles) {
  await page.waitForFunction(
    (n) => {
      const nodes = [...document.querySelectorAll(".react-flow__node")];
      return nodes.length === n && new Set(nodes.map((x) => x.style.transform)).size === n;
    },
    tiles,
    { timeout: 30_000 },
  );
  await page.waitForTimeout(900); // the framing animation
}

async function insidePanel(page, selector) {
  // Every matching control: is its box inside the dock's box, left to right?
  return page.evaluate((sel) => {
    const dock = document.querySelector(".dock")?.getBoundingClientRect();
    if (!dock) return { error: "no .dock" };
    return [...document.querySelectorAll(sel)].map((el) => {
      const r = el.getBoundingClientRect();
      return {
        label: el.getAttribute("aria-label") ?? el.id ?? el.name ?? el.tagName,
        left: Math.round(r.left),
        right: Math.round(r.right),
        dockRight: Math.round(dock.right),
        inside: r.left >= dock.left - 0.5 && r.right <= dock.right + 0.5,
      };
    });
  }, selector);
}

const browser = await chromium.launch();
for (const w of WINDOWS) {
  const tag = `${w.width}x${w.height}`;
  const f = (findings[tag] = {});
  const context = await browser.newContext({ viewport: w, deviceScaleFactor: 2 });
  const page = await context.newPage();
  const shot = (name) => page.screenshot({ path: `${OUT}/${tag}-${name}.png` });

  // 1 · the launchpad, one recording, no key
  await page.goto(APP);
  await page.getByRole("button", { name: /Strait of Hormuz/ }).first().waitFor();
  await page.waitForTimeout(600);
  await shot("01-launchpad");

  // 2 · the map, a claim chosen with the mouse: the way in, in the Inspector's head
  await page.getByRole("button", { name: /Strait of Hormuz/ }).first().click();
  await laidOut(page, 7);
  await page.locator('.react-flow__node[data-id="B"]').click();
  const wayIn = page.getByRole("button", { name: "Change this claim" });
  await wayIn.waitFor();
  await shot("02-inspector-way-in");
  await page.locator(".dock").screenshot({ path: `${OUT}/${tag}-02b-dock-only.png` });

  // 3 · focus: Tab to the way in, Enter — where is the keyboard? Then Done.
  await wayIn.focus();
  await page.keyboard.press("Enter");
  await page.locator('.intervene[data-about="B"]').waitFor();
  await page.waitForTimeout(200);
  f.focusAfterOpen = await page.evaluate(() => {
    const a = document.activeElement;
    return {
      tag: a?.tagName,
      text: (a?.textContent ?? "").trim().slice(0, 60),
      insideOperations: !!a?.closest(".intervene"),
    };
  });
  await page.keyboard.press("Tab");
  f.focusAfterOneTab = await page.evaluate(() => {
    const a = document.activeElement;
    return {
      tag: a?.tagName,
      text: (a?.textContent ?? "").trim().slice(0, 60),
      insideOperations: !!a?.closest(".intervene"),
    };
  });
  await shot("03-operations-open");
  await page.locator(".dock").screenshot({ path: `${OUT}/${tag}-03b-dock-only.png` });
  f.operationsOffered = await page
    .locator(".intervene button")
    .evaluateAll((bs) => bs.map((b) => (b.textContent ?? "").trim().slice(0, 90)));

  // 4 · My own number: three fields inside the panel's right edge
  await page.getByRole("button", { name: /^My own number/ }).click();
  await page.getByLabel(/Your likelihood/).waitFor();
  await page.waitForTimeout(200);
  f.myOwnNumberFields = await insidePanel(page, ".intervene input");
  f.pageScrollsSideways = await page.evaluate(
    () => document.documentElement.scrollWidth > document.documentElement.clientWidth,
  );
  await shot("04-my-own-number");
  await page.locator(".dock").screenshot({ path: `${OUT}/${tag}-04b-dock-only.png` });

  // Done returns the keyboard
  const done = page.locator(".intervene").getByRole("button", { name: /^Done/ });
  if (await done.count()) {
    await done.first().click();
    await page.waitForTimeout(200);
    f.focusAfterDone = await page.evaluate(() => {
      const a = document.activeElement;
      return { tag: a?.tagName, text: (a?.textContent ?? "").trim().slice(0, 60) };
    });
  } else {
    f.focusAfterDone = "no Done button found";
  }

  // 5 · the strike branch: the change list leads with its rows
  await page.keyboard.press("Meta+k");
  await page.getByText(/Every command, by name/).waitFor();
  await shot("05a-palette");
  await page.keyboard.type("Hormuz opens");
  await page.keyboard.press("Enter");
  await page.locator(".map-live", { hasText: "Branch created." }).waitFor({ timeout: 30_000 });
  await laidOut(page, 8);
  await shot("05-strike-branch");
  await page.locator(".dock").screenshot({ path: `${OUT}/${tag}-05b-dock-only.png` });
  f.liveSentence = await page.locator(".map-live").textContent();
  f.tileTitles = await page
    .locator(".react-flow__node [title]")
    .evaluateAll((els) => els.map((e) => e.getAttribute("title")).filter((t) => t && t.length > 20));

  // 6 · greyscale of the same screen
  await page.addStyleTag({ content: "html{filter:grayscale(1)!important}" }).then(async (h) => {
    await page.waitForTimeout(150);
    await shot("06-strike-branch-grey");
    await h.evaluate((el) => el.remove());
  });

  // 7 · the outline: a sentence wide
  await page.locator('.react-flow__node[data-id="B"]').focus();
  await page.keyboard.press("O");
  await page.getByRole("tree").waitFor();
  await page.waitForTimeout(300);
  await shot("07-outline");
  await page.locator(".dock").screenshot({ path: `${OUT}/${tag}-07b-dock-only.png` });
  f.outlineItemWidths = await page
    .locator('[role="treeitem"]')
    .evaluateAll((els) => els.slice(0, 8).map((e) => Math.round(e.getBoundingClientRect().width)));

  await context.close();

  // 8 · the launchpad when the readiness ask never comes back
  const dead = await browser.newContext({ viewport: w, deviceScaleFactor: 2 });
  const deadPage = await dead.newPage();
  await deadPage.route("**/api/**", (route) => route.abort());
  await deadPage.goto(APP);
  await deadPage.waitForTimeout(2500);
  await deadPage.screenshot({ path: `${OUT}/${tag}-08-launchpad-server-gone.png` });
  f.launchpadServerGone = (await deadPage.locator("body").innerText()).slice(0, 1200);
  await dead.close();
}
await browser.close();
writeFileSync(`${OUT}/findings.json`, JSON.stringify(findings, null, 2));
console.log(`wrote ${OUT}`);

